---
import type { Location, Options } from './map-types';

export interface Props {
  locations?: Location[];
  options?: Options;
}

const DEFAULT_LOCATIONS: Location[] = [
  { geo: { lat: -2.269557, lon: 40.900641 }, title: "Lamu Old Town" },
  { geo: { lat: -2.271529, lon: 40.902176 }, title: "Shela Beach" }
];

const { locations = DEFAULT_LOCATIONS, options } = Astro.props;

const baseUrl = 'https://maps.googleapis.com/maps/api/staticmap';
const mapZoom = options?.zoom || 14;
const mapApiKey = options?.api_key || 'YOUR_API_KEY'; // Replace with your key
const markers = locations.map(loc => `${loc.geo.lat},${loc.geo.lon}`).join('|');

const mapUrl = `${baseUrl}?size=600x400&zoom=${mapZoom}&markers=${markers}&key=${mapApiKey}`;
---

<div class="max-w-2xl mx-auto">
  <img src={mapUrl} alt="Static Google Map" class="rounded-lg shadow-md border" />
</div>

---
import type { Location, Options } from './map-types';

const { locations = [
  { geo: { lon: 40.902, lat: -2.2696 }, title: "Shela Beach" },
  { geo: { lon: 40.908, lat: -2.2711 }, title: "Lamu Town" }
], options = {} } : { locations?: Location[]; options?: Options } = Astro.props;

const api_key = options.api_key || import.meta.env.PUBLIC_GOOGLE_MAPS_API_KEY;
const zoom = options.zoom || 14;

const markers = locations.map(loc => `markers=color:red%7Clabel:${encodeURIComponent(loc.title[0])}%7C${loc.geo.lat},${loc.geo.lon}`).join('&');
const center = `${locations[0].geo.lat},${locations[0].geo.lon}`;

const mapUrl = `https://maps.googleapis.com/maps/api/staticmap?center=${center}&zoom=${zoom}&size=600x400&maptype=roadmap&${markers}&key=${api_key}`;
---

<div class="my-4">
  <img src={mapUrl} alt="Google Map" class="rounded shadow-md">
</div>

# Google Maps Static API Component

This Astro component enables easy integration of Google Maps Static API using TailwindCSS for styling.

## Props

```typescript
interface GeoPos {
  lon: number;
  lat: number;
}

interface Location {
  geo: GeoPos;
  title: string;
}

interface Options {
  zoom?: number;
  api_key?: string;
}
```

## Usage

```astro
---
import Map from './map.astro';

const locations: Location[] = [
  { geo: { lon: 40.902, lat: -2.2696 }, title: "Shela Beach" },
  { geo: { lon: 40.908, lat: -2.2711 }, title: "Lamu Town" }
];

const options: Options = { zoom: 14 };
---

<Map {locations} {options} />
```

## API Key Setup

1. Acquire your API key via [Google Maps Platform](https://cloud.google.com/maps-platform/).
2. Ensure you enable the "Static Maps API" service.
3. Add your API key to your project's environment variables:

```
PUBLIC_GOOGLE_MAPS_API_KEY=your_google_maps_api_key
```

Ensure sensitive keys are properly managed to protect your API limits and associated costs.
